import{_ as t,o as r,c as i,b3 as o}from"./chunks/framework.VnelH-cX.js";const l="/docs-imgs/guide/SnowShot_2025-10-28_01-45-09.webp",g=JSON.parse('{"title":"截图历史","description":"","frontmatter":{},"headers":[],"relativePath":"guide/function/captureHistory.md","filePath":"guide/function/captureHistory.md","lastUpdated":1786700458000}'),e={name:"guide/function/captureHistory.md"};function n(s,a,h,d,u,p){return r(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="截图历史" tabindex="-1">截图历史 <a class="header-anchor" href="#截图历史" aria-label="Permalink to &quot;截图历史&quot;">​</a></h1><p>截图历史是 Wing Shot 的核心功能之一，它智能记录每次截图的完整信息，包括显示器画面和截图内容。通过截图历史，您可以轻松回顾过往截图、继续未完成的标注编辑，或快速复用之前的截图内容。</p><p><img src="'+l+'" alt="截图历史界面"></p><h2 id="主要功能" tabindex="-1">主要功能 <a class="header-anchor" href="#主要功能" aria-label="Permalink to &quot;主要功能&quot;">​</a></h2><p>截图历史为您提供了强大的截图管理和回溯能力：</p><ul><li><strong>完整记录</strong>：自动保存每次截图的编辑状态和原始画面</li><li><strong>快速编辑</strong>：一键回到之前的编辑状态，继续进行标注和修改</li><li><strong>便捷复制</strong>：直接复制历史截图到剪贴板，无需重新截取</li><li><strong>灵活筛选</strong>：按来源、时间等条件快速查找需要的截图</li><li><strong>画面回顾</strong>：查看截图时的完整显示器画面，获取更多上下文信息</li></ul><h2 id="核心操作" tabindex="-1">核心操作 <a class="header-anchor" href="#核心操作" aria-label="Permalink to &quot;核心操作&quot;">​</a></h2><h3 id="编辑" tabindex="-1">编辑 <a class="header-anchor" href="#编辑" aria-label="Permalink to &quot;编辑&quot;">​</a></h3><p>点击截图记录的<strong>编辑</strong>按钮，可以立即回到该截图最终编辑时的状态，继续进行标注、裁剪、马赛克等编辑操作。</p><p>这个功能特别适合：</p><ul><li>需要补充标注说明的截图</li><li>发现遗漏信息需要重新编辑</li><li>想要基于之前的编辑创建新版本</li></ul><h3 id="复制" tabindex="-1">复制 <a class="header-anchor" href="#复制" aria-label="Permalink to &quot;复制&quot;">​</a></h3><p>点击<strong>复制</strong>按钮，即可将该截图的编辑结果复制到系统剪贴板中，无需重新截图。</p><p>使用场景：</p><ul><li>快速重复使用之前的截图</li><li>分享历史截图到聊天工具或文档</li><li>避免重复截取相同内容</li></ul><h3 id="删除" tabindex="-1">删除 <a class="header-anchor" href="#删除" aria-label="Permalink to &quot;删除&quot;">​</a></h3><p>对于不再需要的截图记录，可以通过<strong>删除</strong>功能清理对应记录，保持截图历史的整洁。</p><h3 id="预览显示器画面" tabindex="-1">预览显示器画面 <a class="header-anchor" href="#预览显示器画面" aria-label="Permalink to &quot;预览显示器画面&quot;">​</a></h3><p>截图记录默认显示的是经过编辑后的截图结果。通过<strong>鼠标右键点击预览图</strong>，可以切换查看截图时的完整显示器画面。</p><p>这个功能有助于：</p><ul><li>回忆截图时的完整场景</li><li>查看被裁剪掉的周边信息</li><li>确认截图的原始上下文</li></ul><h2 id="筛选和搜索" tabindex="-1">筛选和搜索 <a class="header-anchor" href="#筛选和搜索" aria-label="Permalink to &quot;筛选和搜索&quot;">​</a></h2><p>通过页面右上角的筛选控件，可以快速定位所需的截图记录。</p><h3 id="按来源筛选" tabindex="-1">按来源筛选 <a class="header-anchor" href="#按来源筛选" aria-label="Permalink to &quot;按来源筛选&quot;">​</a></h3><p>支持按以下截图来源进行筛选：</p><ul><li><strong>复制</strong>：复制到剪贴板的截图</li><li><strong>保存</strong>：保存为文件的截图</li><li><strong>固定到屏幕</strong>：固定显示在屏幕上的截图</li><li><strong>截取全屏</strong>：全屏截图记录</li><li><strong>滚动截图-复制</strong>：滚动截图后复制的内容</li><li><strong>滚动截图-保存</strong>：滚动截图后保存的文件</li><li><strong>滚动截图-固定到屏幕</strong>：滚动截图后固定的内容</li></ul><h3 id="按时间筛选" tabindex="-1">按时间筛选 <a class="header-anchor" href="#按时间筛选" aria-label="Permalink to &quot;按时间筛选&quot;">​</a></h3><p>可以按时间范围筛选截图记录，快速找到特定时期的截图。</p><h3 id="手动刷新" tabindex="-1">手动刷新 <a class="header-anchor" href="#手动刷新" aria-label="Permalink to &quot;手动刷新&quot;">​</a></h3><p>如果自动更新出现延迟或失效，可以点击<strong>刷新按钮</strong>手动更新截图历史列表，确保显示最新的截图记录。</p>',30)])])}const _=t(e,[["render",n]]);export{g as __pageData,_ as default};
